import { openFile } from './handles.js';

// Xport: linked views of one file.
export async function openViews(worker, file, combos) {
  const views = [];
  for (const bands of combos.slice(0, 16)) {
    const handle = await openFile(worker, file);
    views.push({ handle, bands });
  }
  return views;
}

export function closeViews(views) {
  for (const view of views) view.handle.close();
}
